import React from "react";
import Card from "./Card";

/**
 * KPI metric card.
 * Props: label, value, sub, icon (Lucide component), color ("orange"|"green"|"blue"|"emerald"|"red"|"amber")
 */
const colorMap = {
  orange:  { iconBg: "bg-orange-100",  iconText: "text-orange-500",  valueText: "text-[var(--accent-2)]" },
  green:   { iconBg: "bg-green-100",   iconText: "text-green-600",   valueText: "text-[var(--success)]" },
  blue:    { iconBg: "bg-blue-100",    iconText: "text-blue-600",    valueText: "text-[var(--info)]" },
  emerald: { iconBg: "bg-emerald-100", iconText: "text-emerald-600", valueText: "text-emerald-600" },
  red:     { iconBg: "bg-red-100",     iconText: "text-red-500",     valueText: "text-[var(--danger)]" },
  amber:   { iconBg: "bg-amber-100",   iconText: "text-amber-600",   valueText: "text-[var(--warning)]" },
  purple:  { iconBg: "bg-purple-100",  iconText: "text-purple-600",  valueText: "text-purple-600" },
};

export default function StatCard({
  label,
  value,
  sub,
  icon: Icon,
  color = "orange",
  trend,
  className = "",
}) {
  const c = colorMap[color] ?? colorMap.orange;
  return (
    <Card className={`flex items-start justify-between ${className}`}>
      <div className="min-w-0 flex-1 pr-3">
        <p
          className="text-xs font-semibold uppercase tracking-wider mb-1.5 truncate"
          style={{ color: "var(--muted)" }}
        >
          {label}
        </p>
        <p className={`text-2xl font-extrabold leading-tight ${c.valueText}`}>
          {value ?? "—"}
        </p>
        {sub && (
          <p className="text-xs mt-1 truncate" style={{ color: "var(--muted)" }}>
            {sub}
          </p>
        )}
        {trend && (
          <p
            className={`text-xs font-semibold mt-1 flex items-center gap-0.5 ${
              trend.dir === "up" ? "text-[var(--success)]" : "text-[var(--danger)]"
            }`}
          >
            {trend.dir === "up" ? "↑" : "↓"} {trend.label}
          </p>
        )}
      </div>
      {Icon && (
        <div className={`${c.iconBg} p-2.5 rounded-xl flex-shrink-0`}>
          <Icon className={c.iconText} style={{ width: 22, height: 22 }} />
        </div>
      )}
    </Card>
  );
}
