import React from "react";
import {
  Sun,
  LayoutDashboard,
  Calculator,
  BarChart3,
  History as HistoryIcon,
  Brain,
  Database,
  Settings,
  ChevronRight,
  X,
  Activity,
  Wifi,
  WifiOff,
  Loader2,
  CheckCircle2,
} from "lucide-react";

const NAV_ITEMS = [
  { id: "dashboard", label: "Dashboard",       Icon: LayoutDashboard },
  { id: "forecast",  label: "Forecast",         Icon: Calculator },
  { id: "analytics", label: "Analytics",        Icon: BarChart3 },
  { id: "history",   label: "History",          Icon: HistoryIcon },
  { id: "training",  label: "Model Training",   Icon: Brain },
  { id: "dataset",   label: "Dataset Builder",  Icon: Database },
  { id: "settings",  label: "Settings",         Icon: Settings },
];

export default function Sidebar({
  activeTab,
  onNavigate,
  isOpen,
  onClose,
  apiStatus,
  totalForecastCount,
  isDemo,
  forecastResult,
}) {
  return (
    <>
      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 z-20 lg:hidden"
          style={{ background: "rgba(0,0,0,0.45)" }}
          onClick={onClose}
        />
      )}

      <aside
        className={`
          fixed top-0 left-0 h-full z-30 flex flex-col
          sidebar-transition
          ${isOpen ? "translate-x-0" : "-translate-x-full"}
          lg:translate-x-0 lg:static lg:z-auto lg:flex
        `}
        style={{
          width: 240,
          background: "var(--surface)",
          borderRight: "1px solid var(--border)",
          boxShadow: "var(--shadow-sm)",
        }}
      >
        {/* Brand */}
        <div
          className="h-14 flex items-center px-4 shrink-0"
          style={{ borderBottom: "1px solid var(--border)" }}
        >
          <div
            className="flex items-center justify-center w-8 h-8 rounded-lg mr-2.5 shrink-0"
            style={{ background: "rgba(249,115,22,0.12)" }}
          >
            <Sun style={{ width: 17, height: 17, color: "var(--accent-2)" }} />
          </div>
          <div className="min-w-0 flex-1">
            <p
              className="text-sm font-extrabold leading-tight tracking-tight truncate"
              style={{ color: "var(--text)" }}
            >
              SolarCast Pro
            </p>
            <p className="text-xs leading-tight truncate" style={{ color: "var(--muted)" }}>
              ML Forecasting
            </p>
          </div>
          <button
            className="lg:hidden ml-2 rounded-md p-1 focus:outline-none"
            style={{ color: "var(--muted)" }}
            onClick={onClose}
          >
            <X style={{ width: 16, height: 16 }} />
          </button>
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto py-3 px-2 space-y-0.5">
          {NAV_ITEMS.map(({ id, label, Icon }) => {
            const active = activeTab === id;
            return (
              <button
                key={id}
                onClick={() => { onNavigate(id); onClose(); }}
                className={`nav-item w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors text-left ${active ? "nav-active font-semibold" : ""}`}
                style={{ color: active ? "var(--accent-2)" : "var(--text-secondary)" }}
              >
                <Icon
                  style={{
                    width: 17,
                    height: 17,
                    flexShrink: 0,
                    color: active ? "var(--accent-2)" : "var(--muted)",
                  }}
                />
                <span className="flex-1 truncate">{label}</span>
                {active && (
                  <ChevronRight style={{ width: 14, height: 14, color: "var(--accent-2)", opacity: 0.7 }} />
                )}
              </button>
            );
          })}
        </nav>

        {/* Footer: status */}
        <div
          className="px-4 py-4 space-y-2 shrink-0"
          style={{ borderTop: "1px solid var(--border)" }}
        >
          <p
            className="text-xs font-bold uppercase tracking-wider mb-2"
            style={{ color: "var(--muted)" }}
          >
            System
          </p>

          <StatusRow
            label="API"
            value={
              apiStatus === "online"
                ? "Connected"
                : apiStatus === "offline"
                ? "Offline"
                : "Checking"
            }
            color={
              apiStatus === "online"
                ? "var(--success)"
                : apiStatus === "offline"
                ? "var(--danger)"
                : "var(--warning)"
            }
            Icon={
              apiStatus === "online"
                ? Wifi
                : apiStatus === "offline"
                ? WifiOff
                : Loader2
            }
            iconSpin={apiStatus === "checking"}
          />
          <StatusRow
            label="Forecasts"
            value={`${totalForecastCount} runs`}
          />
          <StatusRow
            label="Mode"
            value={isDemo ? "Demo" : forecastResult ? "Live" : "Ready"}
            color={isDemo ? "var(--warning)" : forecastResult ? "var(--success)" : "var(--muted)"}
          />
        </div>
      </aside>
    </>
  );
}

function StatusRow({ label, value, color, Icon, iconSpin }) {
  return (
    <div className="flex items-center justify-between text-xs">
      <span style={{ color: "var(--muted)" }}>{label}</span>
      <span
        className="font-semibold flex items-center gap-1"
        style={{ color: color || "var(--text)" }}
      >
        {Icon && (
          <Icon style={{ width: 12, height: 12 }} className={iconSpin ? "animate-spin" : ""} />
        )}
        {value}
      </span>
    </div>
  );
}
